from trl import GRPOConfig
import inspect
sig = inspect.signature(GRPOConfig.__init__)
params = list(sig.parameters.keys())
for p in ['max_completion_length', 'max_prompt_length', 'num_generations', 'temperature', 'beta']:
    if p in params:
        print(f'OK {p} exists in GRPOConfig')
    else:
        print(f'MISSING {p} from GRPOConfig')
if 'max_seq_length' in params:
    print('OK max_seq_length exists')
elif 'max_length' in params:
    print('WARN max_length exists (not max_seq_length)')
else:
    print('MISSING neither max_seq_length nor max_length')
print()
print('All GRPOConfig params:', sorted(params))
"
